ALTER TABLE "UserSettings" ADD COLUMN "enabledModules" text[] NOT NULL DEFAULT ARRAY['finances','education','calendar','career','projects','goals','notes','assistant'];
CREATE TABLE "VoiceSession"(id uuid PRIMARY KEY,"userId" uuid NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,domains text[] NOT NULL,"expiresAt" timestamptz NOT NULL,"closedAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT now(),UNIQUE(id,"userId"));
CREATE TABLE "VoiceTurn"(id uuid PRIMARY KEY,"userId" uuid NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,"sessionId" uuid NOT NULL,"requestId" uuid NOT NULL,transcript varchar(1000),answer jsonb,status text NOT NULL CHECK(status IN('generating','completed','failed')),"sttUsageId" uuid,"chatUsageId" uuid,"createdAt" timestamptz NOT NULL DEFAULT now(),FOREIGN KEY("sessionId","userId")REFERENCES "VoiceSession"(id,"userId")ON DELETE CASCADE,UNIQUE("userId","requestId"));
CREATE INDEX voice_customer_session ON "VoiceSession"("userId","expiresAt");
CREATE INDEX voice_customer_turn ON "VoiceTurn"("userId","sessionId","createdAt");
DO $$ DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['VoiceSession','VoiceTurn'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',tab);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',tab);EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON public.%I TO pluto_app',tab);EXECUTE format('CREATE POLICY voice_self ON public.%I TO pluto_app USING("userId"=auth.uid() AND EXISTS(SELECT 1 FROM public."User" WHERE id=auth.uid() AND status=''active'')) WITH CHECK("userId"=auth.uid() AND EXISTS(SELECT 1 FROM public."User" WHERE id=auth.uid() AND status=''active''))',tab);END LOOP;END $$;
CREATE FUNCTION public.pluto_erase_voice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NEW.status='deleted' AND OLD.status<>'deleted' THEN DELETE FROM public."VoiceSession" WHERE "userId"=NEW.id;END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.pluto_erase_voice() FROM PUBLIC;
CREATE TRIGGER pluto_erase_voice AFTER UPDATE OF status ON "User" FOR EACH ROW EXECUTE FUNCTION public.pluto_erase_voice();
